@extends('layouts.admin') @section('content')<main class="admin-profile p-5 lg:p-8"><a class="text-sm text-sky-600" href="{{ route('admin.projects.index') }}">← Projects</a><h1 class="mt-4 text-4xl font-bold">{{ $project->exists ? 'Edit' : 'Add' }} project</h1><form method="POST" action="{{ $action }}" enctype="multipart/form-data" class="mt-8 space-y-6">@csrf @if($project->exists) @method('PUT') @endif<section class="admin-card grid gap-5 p-6 md:grid-cols-2"><h2 class="md:col-span-2 text-xl font-semibold">Project basics</h2><label class="text-sm">Title<input required name="title" value="{{ old('title',$project->title) }}" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"></label><label class="text-sm">Slug<input name="slug" value="{{ old('slug',$project->slug) }}" placeholder="Generated from title" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"></label><label class="text-sm md:col-span-2">Short description<input required name="short_description" value="{{ old('short_description',$project->short_description) }}" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"></label><label class="text-sm md:col-span-2">Description<textarea required name="description" rows="6" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3">{{ old('description',$project->description) }}</textarea></label><label class="text-sm">Status<select name="status" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3">@foreach(['draft','in_progress','completed','archived'] as $status)<option value="{{ $status }}" @selected(old('status',$project->status ?: 'draft')===$status)>{{ ucfirst(str_replace('_',' ',$status)) }}</option>@endforeach</select></label><label class="flex items-center gap-2 pt-7 text-sm"><input type="checkbox" name="featured" value="1" @checked(old('featured',$project->featured))> Featured project</label></section><section class="admin-card grid gap-5 p-6 md:grid-cols-2"><h2 class="md:col-span-2 text-xl font-semibold">Technologies and links</h2><div class="md:col-span-2 grid gap-2 sm:grid-cols-3">@foreach($technologies as $technology)<label class="flex items-center gap-2 text-sm"><input type="checkbox" name="technology_ids[]" value="{{ $technology->id }}" @checked(in_array($technology->id,old('technology_ids',$project->technologies->pluck('id')->all())))>{{ $technology->name }}</label>@endforeach</div><label class="text-sm">GitHub URL<input name="github_url" value="{{ old('github_url',$project->github_url) }}" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"></label><label class="text-sm">Demo URL<input name="demo_url" value="{{ old('demo_url',$project->demo_url) }}" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"></label></section><section class="admin-card grid gap-5 p-6 md:grid-cols-2"><h2 class="md:col-span-2 text-xl font-semibold">Cover image</h2><label class="text-sm">Upload cover<input id="cover_image" type="file" name="cover_image" accept="image/*" class="mt-2 block"></label><div id="cover-preview" class="h-32 rounded-xl bg-slate-100">@if($project->cover_image)<img src="{{ asset('storage/'.$project->cover_image) }}" class="h-full w-full rounded-xl object-cover" alt="Cover preview">@endif</div></section><section class="admin-card grid gap-5 p-6 md:grid-cols-2"><h2 class="md:col-span-2 text-xl font-semibold">Project story</h2>@foreach([['problem','Problem'],['solution','Solution'],['objectives','Objectives'],['responsibilities','Responsibilities'],['challenges','Challenges'],['architecture','Architecture']] as [$field,$label])<label class="text-sm">{{ $label }}<textarea name="{{ $field }}" rows="4" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3">{{ old($field,$project->{$field}) }}</textarea></label>@endforeach</section><button class="rounded-lg bg-sky-500 px-6 py-3 font-semibold text-white">Save project</button></form><script>document.getElementById('cover_image')?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=x=>document.getElementById('cover-preview').innerHTML='<img src="'+x.target.result+'" class="h-full w-full rounded-xl object-cover" alt="Selected cover">';r.readAsDataURL(f)});</script></main>@endsection
